"use client";
import { GuideWorkspace, GuideInspection, GuideEntry } from "./guide-workspace";
import { ExportWorkspace } from "./export-workspace";
import { SourceWorkspace } from "./source-workspace";
import { JobWorkspace } from "./job-workspace";
import { TemplateWorkspace } from "./template-workspace";

import { useEffect, useMemo, useState } from "react";
import { PageHeader, StatePanel, StatusBadge } from "./ui";
import { AnalysisWorkspace, ImpactAssessmentRoute } from "./analysis-workspace";
import { EvidenceWorkspace } from "./evidence-workspace";
import { WorkbookSurface } from "./workbooks";

type Tone = "neutral" | "info" | "warning" | "critical" | "success";

const dealBase = (dealId: string) => `/app/deals/${dealId}`;

const titleCase = (value: string) => value.replace(/[-_]/g, " ").replace(/\b\w/g, (letter) => letter.toUpperCase());

function MetricGrid({ items }: { items: Array<{ label: string; value: string; detail: string; tone?: Tone }> }) {
  return <div className="dc-grid-three">{items.map((item) => <article className="dc-surface-card" key={item.label}><span className="dc-eyebrow">{item.label}</span><h2>{item.value}</h2><p>{item.detail}</p>{item.tone ? <StatusBadge tone={item.tone}>{item.tone}</StatusBadge> : null}</article>)}</div>;
}

function TabList({ labels }: { labels: string[] }) {
  const [active, setActive] = useState(labels[0]);
  return <div className="dc-tab-list" role="tablist" aria-label="Detail sections">{labels.map((label) => <button key={label} type="button" role="tab" aria-selected={active === label} className={active === label ? "is-active" : ""} onClick={() => setActive(label)}>{label}</button>)}</div>;
}

function CollectionSurface({ dealId, kind, title, description, rows }: { dealId: string; kind: string; title: string; description: string; rows: Array<{ id: string; name: string; state: string; detail: string; tone: Tone }> }) {
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState("All");
  const [notice, setNotice] = useState("");
  const filters = ["All", ...Array.from(new Set(rows.map((row) => row.state)))];
  const visible = useMemo(() => rows.filter((row) => {
    const matchesQuery = `${row.id} ${row.name} ${row.detail}`.toLowerCase().includes(query.toLowerCase());
    return matchesQuery && (filter === "All" || row.state === filter);
  }), [filter, query, rows]);
  return <>
    <PageHeader eyebrow={`Deal workspace · ${kind}`} title={title} description={description} actions={<><StatusBadge tone="info">Synthetic fixture</StatusBadge><span className="dc-mono">REV 0.4</span></>} />
    <div className="dc-toolbar"><label className="dc-search-field"><span className="dc-sr-only">Search {title}</span><input type="search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder={`Search ${kind.toLowerCase()}...`} /></label><div className="dc-filter-list" aria-label={`${title} filters`}>{filters.map((item) => <button key={item} type="button" className={filter === item ? "is-active" : ""} onClick={() => setFilter(item)}>{item}</button>)}</div></div>
    <section className="dc-surface-card"><div className="dc-table-wrap"><table><thead><tr><th>Exact object</th><th>Status</th><th>Summary</th><th>Next action</th></tr></thead><tbody>{visible.map((row) => <tr key={row.id}><td><strong className="dc-mono">{row.id}</strong><br /><span>{row.name}</span></td><td><StatusBadge tone={row.tone}>{row.state}</StatusBadge></td><td>{row.detail}</td><td><button type="button" className="dc-button dc-button-secondary" onClick={() => setNotice(`${row.id} opened in the canonical ${kind.toLowerCase()} detail surface.`)}>Inspect</button></td></tr>)}</tbody></table></div>{visible.length === 0 ? <StatePanel tone="info" label="Search state" title="No matching records" detail="Clear the search or filter to return to the full synthetic collection." /> : null}{notice ? <p className="dc-inline-notice" role="status">{notice}</p> : null}</section>
  </>;
}

function ObjectDetailSurface({ dealId, kind, id, title, description, status = "Review required", fields }: { dealId: string; kind: string; id: string; title: string; description: string; status?: string; fields: Array<[string, string]> }) {
  const [active, setActive] = useState("Overview");
  return <>
    <PageHeader eyebrow={`Object detail · ${kind}`} title={title} description={description} actions={<><StatusBadge tone={status === "Ready" ? "success" : status === "Blocked" ? "critical" : "warning"}>{status}</StatusBadge><span className="dc-mono">{id}</span></>} />
    <div className="dc-tab-list" role="tablist" aria-label={`${kind} detail tabs`}>{["Overview", "Lineage", "History", "Controls"].map((tab) => <button key={tab} type="button" role="tab" aria-selected={active === tab} className={active === tab ? "is-active" : ""} onClick={() => setActive(tab)}>{tab}</button>)}</div>
    {active === "Overview" ? <section className="dc-surface-card"><dl>{fields.map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl></section> : <section className="dc-surface-card"><h2>{active} for {id}</h2><p>This tab preserves the exact object boundary. It shows synthetic evidence only and does not mutate the authoritative record.</p><StatePanel tone={active === "Controls" ? "warning" : "info"} label="View state" title={`${active} is inspectable`} detail="Use the canonical review action when a decision or revision is required." /></section>}
    <p className="dc-back-links"><a href={`${dealBase(dealId)}/${kind === "source" ? "sources" : kind === "claim" ? "evidence-decisions" : kind === "analysis" ? "analysis" : kind === "buyer" ? "auction-process" : "execution-package"}`}>← Back to {kind} collection</a></p>
  </>;
}

function EvidenceInspectorSurface({ dealId }: { dealId: string }) {
  const dimensions = [["Independent extraction", "Complete", "Workbook cell preserved"], ["Evidence coverage", "Complete", "Targeted parser coverage"], ["Source authority", "Provided under mandate", "Client-supplied Source Record"], ["Freshness", "Unassessed", "Requires Banker review"], ["Conflict", "Material conflict", "Two Claims retained"], ["Calculation", "Not applicable", "No derived result"], ["Model", "Not applicable", "No model assertion"], ["Professional judgment", "Not assessed", "Decision required"], ["Intended use", "Bounded internal analysis", "Valuation cross-check only"]];
  return <><PageHeader eyebrow="Deal workspace · Evidence Inspector" title="Evidence & Decisions" description="Inspect exact Source fragments and typed Claims. Each readiness dimension is independent; there is no scalar truth score or automatic promotion." actions={<><StatusBadge tone="info">Synthetic fixture</StatusBadge><span className="dc-mono">REV 0.4</span></>} /><section className="dc-surface-card"><div className="dc-grid-two"><div><span className="dc-eyebrow">Selected Evidence</span><h2>Management Accounts · Operating Case!F42</h2><p>Adjusted EBITDA was 17.8 million. The accepted Evidence points to one exact Source Record, Representation and native locator.</p><dl><div><dt>Source Record</dt><dd className="dc-mono">SR-002 · v1</dd></div><div><dt>Representation</dt><dd className="dc-mono">REP-002 · original</dd></div><div><dt>Locator</dt><dd className="dc-mono">Operating Case!F42</dd></div><div><dt>Lineage</dt><dd>Source Record → native Representation → Evidence</dd></div></dl></div><div><span className="dc-eyebrow">Control boundary</span><StatePanel tone="warning" label="Banker action required" title="Evidence is not a Fact" detail="Accepting a source relationship never creates a Fact. A typed Banker Decision must state the exact scope, purpose, alternatives, rationale and downstream effect." /><a className="dc-button" href={`${dealBase(dealId)}/evidence-decisions/control-review`}>Open Human Decision review</a></div></div></section><section className="dc-surface-card"><h2>Independent Evidence dimensions</h2><div className="dc-table-wrap"><table><thead><tr><th>Dimension</th><th>Posture</th><th>Basis</th></tr></thead><tbody>{dimensions.map(([label, state, basis]) => <tr key={label}><td><strong>{label}</strong></td><td><StatusBadge tone={state === "Complete" ? "success" : state === "Material conflict" ? "critical" : "warning"}>{state}</StatusBadge></td><td>{basis}</td></tr>)}</tbody></table></div><p className="dc-inline-notice">No truth score, confidence scalar or readiness shortcut is calculated.</p></section><section className="dc-surface-card"><h2>Typed Claims retained</h2><div className="dc-table-wrap"><table><thead><tr><th>Claim</th><th>Exact value</th><th>Status</th><th>Action</th></tr></thead><tbody><tr><td><strong className="dc-mono">CLM-018-A</strong><br />Seller CIM basis</td><td>$18.4m · FY2025E</td><td><StatusBadge tone="warning">Claim</StatusBadge></td><td><a className="dc-inline-button" href={`${dealBase(dealId)}/claims/clm-018`}>Inspect →</a></td></tr><tr><td><strong className="dc-mono">CLM-018-B</strong><br />Management model basis</td><td>$17.8m · FY2025E</td><td><StatusBadge tone="warning">Conflict retained</StatusBadge></td><td><a className="dc-inline-button" href={`${dealBase(dealId)}/evidence-decisions/control-review`}>Resolve in review →</a></td></tr></tbody></table></div></section></>;
}

function DecisionReviewSurface({ dealId }: { dealId: string }) {
  const [ebitdaChoice, setEbitdaChoice] = useState("17.8");
  const [cashValue, setCashValue] = useState("4.7");
  const [rationale, setRationale] = useState("");
  const [errors, setErrors] = useState<string[]>([]);
  const [recorded, setRecorded] = useState(false);
  useEffect(() => { setRecorded(window.localStorage.getItem(`analysis-decision-recorded:${dealId}`) === "true"); }, [dealId]);
  const submit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const next: string[] = [];
    if (ebitdaChoice !== "17.8") next.push("This flow requires the $17.8m controlled treatment that matches the exact Source Record.");
    if (cashValue !== "4.7") next.push("The corrected Cash value must match $4.7m at SR-002 / Balance Sheet!F28.");
    if (rationale.trim().length < 20) next.push("Enter at least 20 characters explaining the Decision scope, basis, and preserved matters.");
    setErrors(next);
    if (next.length === 0) { window.localStorage.setItem(`analysis-decision-recorded:${dealId}`, "true"); setRecorded(true); }
  };
  if (recorded) return <div className="dc-analysis-page"><PageHeader eyebrow="Historical control receipt" title="Human Decision DEC-014" description="This immutable record has been created and cannot be edited in place. A correction must create a new record from the current control context." actions={<StatusBadge tone="success">Recorded · immutable</StatusBadge>} /><section className="dc-analysis-decision" data-od-id="immutable-decision-receipt"><div><span className="dc-eyebrow">Recorded · 2026-08-04 15:12</span><h2>Rev 0.3 valuation treatment recorded</h2><p>$17.8m is the controlled treatment for this scope. The $18.4m seller Claim and AI extraction v1 remain in history. Cash is corrected to $4.7m.</p></div><a className="dc-button" href={`${dealBase(dealId)}/analysis`}>Continue to deterministic validation</a></section></div>;
  return <div className="dc-analysis-page"><p className="dc-back-links"><a href={`${dealBase(dealId)}/evidence-decisions`}>← Return to Evidence</a></p><PageHeader eyebrow="Material Control Review · CLM-018 v2" title="Record the material controlled treatment for Rev 0.3" description="This is not an approval of AI. Submission creates an immutable Human Decision bound to the Deal, object, version, purpose, Evidence, Impact, rationale, and time." actions={<StatusBadge tone="warning">Awaiting Banker Decision</StatusBadge>} />{errors.length ? <div className="dc-analysis-blocker" role="alert" tabIndex={-1} data-od-id="decision-error-summary"><div><span className="dc-eyebrow">Review required</span><h2>Review the fields that require attention</h2><ul>{errors.map((error) => <li key={error}>{error}</li>)}</ul></div></div> : null}<form className="dc-decision-form" onSubmit={submit} noValidate data-od-id="decision-review-form"><section className="dc-surface-card" data-od-id="decision-scope"><span className="dc-eyebrow">01 · Exact object and scope</span><h2>Inspect the immutable context that this submission will bind.</h2><dl><div><dt>Deal</dt><dd>Project Northstar</dd></div><div><dt>Object</dt><dd className="dc-mono">CLM-018 v2</dd></div><div><dt>Purpose</dt><dd>Rev 0.3 internal valuation and CIM preparation</dd></div><div><dt>Source Packet</dt><dd className="dc-mono">SP-004 v2</dd></div><div><dt>External use</dt><dd><StatusBadge tone="critical">Not authorized</StatusBadge></dd></div></dl></section><section className="dc-surface-card" data-od-id="ebitda-control-choice"><span className="dc-eyebrow">02 · Controlled treatment</span><h2>Select the EBITDA controlled treatment</h2><p>The selection applies only to the stated purpose. The other Claim is preserved.</p><fieldset><legend className="dc-sr-only">EBITDA controlled treatment</legend><label className="dc-check-row"><input type="radio" name="ebitda" value="17.8" checked={ebitdaChoice === "17.8"} onChange={(event) => setEbitdaChoice(event.target.value)} /><span><strong>$17.8m</strong> · SR-002 v7 · Operating Case!F42 · QoE adjusted</span></label><label className="dc-check-row"><input type="radio" name="ebitda" value="18.4" checked={ebitdaChoice === "18.4"} onChange={(event) => setEbitdaChoice(event.target.value)} /><span><strong>$18.4m</strong> · SR-001 v3 · display page 18 · seller Claim</span></label></fieldset></section><section className="dc-surface-card" data-od-id="cash-correction"><span className="dc-eyebrow">03 · Cash correction</span><h2>Append a Cash-extraction correction</h2><p>The original AI extraction v1 is not overwritten.</p><div className="dc-grid-two"><label>Original extraction<input value="$6.2m" disabled /><small>AI Proposal v1 · Preserved in history</small></label><label>Corrected Cash (USD millions)<input className="dc-mono" inputMode="decimal" value={cashValue} onChange={(event) => setCashValue(event.target.value)} required /><small>Based on SR-002 / Balance Sheet!F28</small></label></div></section><section className="dc-surface-card" data-od-id="decision-rationale"><span className="dc-eyebrow">04 · Rationale and boundaries</span><h2>Record rationale, boundaries, and preserved matters</h2><label>Decision rationale<textarea value={rationale} onChange={(event) => setRationale(event.target.value)} placeholder="Explain the Decision scope, basis, and preserved matters." rows={5} required /><small>{rationale.trim().length} / 20 characters minimum</small></label></section><aside className="dc-surface-card" data-od-id="decision-summary"><span className="dc-eyebrow">Record to be created</span><h2>Human Decision DEC-014</h2><p><strong>$17.8m EBITDA</strong> · Cash $6.2m → $4.7m</p><p>Preserve both Claims and the original extraction. Deterministic validation may rerun; QC and external use remain separate.</p><button type="submit">Record treatment and Cash correction</button></aside></form></div>;
}

function ReviewActionSurface({ dealId, mode }: { dealId: string; mode: "decision" | "stage" | "external" | "external-event" | "recipient" | "archive" | "delete" | "export" | "lifecycle" }) {
  const config = {
    decision: { eyebrow: "Control review · Evidence", title: "Record a scoped Human Decision", description: "Resolve the exact Claim conflict without overwriting either source value or silently widening scope.", label: "Decision posture", tone: "warning" as Tone, primary: "Record scoped decision" },
    stage: { eyebrow: "Control review · Auction", title: "Review stage transition", description: "Confirm the stage boundary, affected buyers and resulting Process Event before moving the Deal.", label: "Transition posture", tone: "warning" as Tone, primary: "Record stage transition" },
    external: { eyebrow: "Authorization · External use", title: "Create External-Use Decision", description: "Authorize one exact Revision and scope only after readiness and QC evidence are complete.", label: "Authorization posture", tone: "critical" as Tone, primary: "Save decision draft" },
    "external-event": { eyebrow: "External-use event · New", title: "Record actual external use", description: "Record who actually used an authorized Revision, when, and how. Actual use never changes the authorization itself.", label: "Event posture", tone: "info" as Tone, primary: "Record Actual External Use" },
    recipient: { eyebrow: "Delivery · Recipient Access", title: "Create Recipient Access", description: "Separate Delivery preparation from actual external use. A single sensitive-action grant is required at execution.", label: "Recipient posture", tone: "critical" as Tone, primary: "Stage recipient access" },
    archive: { eyebrow: "History · Archive Package", title: "Create Archive Package", description: "Select an append-only package boundary with exact inclusions, exclusions and Manifest receipt.", label: "Archive posture", tone: "info" as Tone, primary: "Stage archive package" },
    delete: { eyebrow: "Lifecycle · Deletion", title: "Review deletion request", description: "Deletion is separate from archive and cancellation and requires an exact typed confirmation plus reauthentication.", label: "High-risk action", tone: "critical" as Tone, primary: "Prepare deletion review" },
    export: { eyebrow: "History · Internal export", title: "Review Internal Controlled Export", description: "Inspect exact content, hashes, restrictions and Receipt before creating a controlled export.", label: "Export posture", tone: "info" as Tone, primary: "Stage export review" },
    lifecycle: { eyebrow: "Controls · Lifecycle", title: "Deal lifecycle", description: "Archive and restore preserve history and capacity consequences; neither action deletes Deal material.", label: "Lifecycle posture", tone: "warning" as Tone, primary: "Stage lifecycle action" },
  }[mode];
  const [submitted, setSubmitted] = useState(false);
  const [phrase, setPhrase] = useState("");
  const requiresPhrase = mode === "delete";
  return <>
    <PageHeader eyebrow={config.eyebrow} title={config.title} description={config.description} actions={<StatusBadge tone={config.tone}>{config.label}</StatusBadge>} />
    <section className="dc-surface-card"><div className="dc-grid-two"><div><span className="dc-eyebrow">Current object</span><h2>{mode === "decision" ? "CLM-018 · EBITDA basis conflict" : mode === "stage" ? "Auction Process · Preparation → Buyer outreach" : mode === "external" ? "DEL-004 · Revision 0.4" : mode === "external-event" ? "RA-018 · Northfield Capital" : "Project Northstar"}</h2><p>All values, actors, timestamps and IDs on this screen are synthetic and Deal-scoped.</p></div><div><span className="dc-eyebrow">Required evidence</span><ul><li>Exact scope and current Revision</li><li>Actor, reason and recorded timestamp</li><li>Downstream consequence and recovery path</li></ul></div></div>{mode === "decision" ? <div className="dc-grid-two"><div><span className="dc-eyebrow">Evidence basis</span><ul><li>18.4m · seller CIM · exact Source locator</li><li>17.8m · management model · exact Source locator</li><li>Conflict remains unresolved until this review</li><li>No averaging or overwrite is permitted</li></ul></div><div><span className="dc-eyebrow">Decision record</span><dl><div><dt>Actor</dt><dd>Authenticated Banker · current session</dd></div><div><dt>Controlled object / version</dt><dd className="dc-mono">CLM-018 · Claim v1</dd></div><div><dt>Effective time</dt><dd>Recorded at submission</dd></div><div><dt>Downstream effect</dt><dd>Valuation cross-check only; affected outputs held for review</dd></div></dl></div></div> : null}<form className="dc-review-form" onSubmit={(event) => { event.preventDefault(); if (mode === "decision" && typeof window !== "undefined") window.localStorage.setItem(`analysis-decision-recorded:${dealId}`, "true"); setSubmitted(true); }}><label htmlFor="scope">Exact scope<select id="scope" defaultValue="current"><option value="current">Current synthetic Deal / Revision 0.4</option><option value="bounded">Bounded review subset only</option></select></label><label htmlFor="reason">Rationale<textarea id="reason" defaultValue={mode === "external-event" ? "Recipient opened Revision 0.4 in the secure Viewer without downloading or forwarding." : "Retain the source lineage and record the smallest scoped control action."} rows={4} /></label>{mode === "decision" ? <><label htmlFor="alternatives">Alternatives considered<textarea id="alternatives" defaultValue="Retain both values with bounded purpose; select one source basis only after contrary evidence review." rows={3} /></label><label htmlFor="contrary">Contrary Evidence / conditions<textarea id="contrary" defaultValue="Seller CIM remains contrary Evidence; re-open if Source version, method, audience or purpose changes." rows={3} /></label></> : null}{requiresPhrase ? <label htmlFor="confirm-phrase">Typed confirmation<input id="confirm-phrase" value={phrase} onChange={(event) => setPhrase(event.target.value)} placeholder="Type DELETE PROJECT NORTHSTAR" /></label> : null}<label className="dc-check-row"><input type="checkbox" required /> I confirm the exact scope and understand this action is append-only.</label><button type="submit" disabled={requiresPhrase && phrase !== "DELETE PROJECT NORTHSTAR"}>{config.primary}</button></form>{submitted ? <StatePanel tone="success" label="Receipt staged" title={mode === "external-event" ? "USE-018 appended to history" : "Review checkpoint recorded"} detail={mode === "external-event" ? "Actual use is recorded separately; EUD-018 and the authorized Revision were not modified." : "No production export, external authorization, deletion, or Process Event was created by this development UI."} /> : null}</section>
    <p className="dc-back-links"><a href={`${dealBase(dealId)}/overview`}>← Return to Deal Overview</a></p>
  </>;
}

function ReadinessSurface({ dealId }: { dealId: string }) {
  const [expanded, setExpanded] = useState<string | null>(null);
  const rows = [["Source lineage", "Ready", "SR-002 and SP-004 have exact locators"], ["Deterministic validation", "Blocked", "Cash correction must be re-reviewed"], ["Native artifact", "Ready", "XLSX Native Artifact is available"], ["Reader Copy", "Review required", "Parity finding remains open"], ["QC", "Blocked", "QC-022 awaits disposition"], ["External use", "Not authorized", "Exact Revision decision is required"]];
  return <><PageHeader eyebrow="Review & readiness" title="Package Readiness" description="A blocker-first matrix for the exact package Revision. There is no aggregate score and no readiness shortcut." actions={<StatusBadge tone="warning">Blocker-first</StatusBadge>} /><section className="dc-surface-card"><div className="dc-table-wrap"><table><thead><tr><th>Dimension</th><th>Posture</th><th>Evidence</th></tr></thead><tbody>{rows.map(([label, state, detail]) => <tr key={label}><td><strong>{label}</strong></td><td><StatusBadge tone={state === "Ready" ? "success" : state === "Blocked" ? "critical" : "warning"}>{state}</StatusBadge></td><td><button type="button" className="dc-inline-button" onClick={() => setExpanded(expanded === label ? null : label)}>{expanded === label ? "Hide detail" : "Inspect detail"}</button>{expanded === label ? <p className="dc-expanded-detail">{detail}</p> : null}</td></tr>)}</tbody></table></div><StatePanel tone="warning" label="Current readiness" title="Not ready for external use" detail="Resolve deterministic validation, QC and exact Revision authorization before any delivery path." /></section><p className="dc-back-links"><a href={`${dealBase(dealId)}/execution-package`}>← Return to Execution Package</a></p></>;
}

function PackageSurface({ dealId }: { dealId: string }) {
  return <><PageHeader eyebrow="Deal workspace · execution package" title="Execution Package" description="Inspect applicability, exact Revision, Native Artifact, Reader Copy, QC and external-use boundaries as one controlled package." actions={<StatusBadge tone="warning">Review required</StatusBadge>} /><MetricGrid items={[{ label: "Current Revision", value: "0.4", detail: "Revision 0.3 remains preserved" }, { label: "Native Artifact", value: "XLSX", detail: "Exact hash and locator profile available", tone: "success" }, { label: "Reader Copy", value: "PDF", detail: "Parity finding QC-022 remains open", tone: "warning" }]} /><section className="dc-surface-card"><h2>Package contents</h2><div className="dc-grid-two"><ul><li>Source lineage and deterministic validation receipt</li><li>Native XLSX and PDF Reader Copy</li><li>QC findings and Impact Assessment</li></ul><ul><li>Revision and authorization boundary</li><li>Internal Controlled Export Manifest</li><li>External-use status: not authorized</li></ul></div><div className="dc-page-actions"><a className="dc-button" href={`${dealBase(dealId)}/review-readiness/package-readiness`}>Open Package Readiness</a><a className="dc-button dc-button-secondary" href={`${dealBase(dealId)}/deliverables/del-004`}>Inspect deliverable</a></div></section></>;
}

function HistorySurface({ dealId }: { dealId: string }) {
  return <><PageHeader eyebrow="Deal workspace · history" title="History & Portability" description="Append-only views for revisions, exports, reimports and lifecycle events. History does not rewrite current truth." actions={<StatusBadge tone="info">Append-only</StatusBadge>} /><MetricGrid items={[{ label: "Revisions", value: "4", detail: "0.1 through 0.4 retained" }, { label: "Exports", value: "1", detail: "Internal Controlled Export staged", tone: "info" }, { label: "Lifecycle", value: "Active", detail: "Archive and restore remain available", tone: "success" }]} /><section className="dc-surface-card"><h2>Portability ledger</h2><div className="dc-table-wrap"><table><thead><tr><th>Event</th><th>Exact boundary</th><th>Posture</th><th>Action</th></tr></thead><tbody>{[["Revision entered", "Revision 0.4 · SR-006 appended", "Recorded", `${dealBase(dealId)}/deliverables/del-004/revisions/compare`], ["Internal export", "EXP-0042 · Manifest preserved", "Review required", `${dealBase(dealId)}/history-portability/internal-export`], ["Reimport comparison", "RI-004 · offline edit vs workspace", "Review required", `${dealBase(dealId)}/history-portability/reimports/ri-004`], ["Archive package", "ARCH-004 · exclusions explicit", "Available", `${dealBase(dealId)}/history-portability/archive-packages/new`]].map(([event, boundary, status, href]) => <tr key={event}><td><strong>{event}</strong></td><td>{boundary}</td><td><StatusBadge tone={status === "Recorded" ? "success" : "warning"}>{status}</StatusBadge></td><td><a className="dc-inline-button" href={href}>Inspect →</a></td></tr>)}</tbody></table></div></section></>;
}

function AnalysisSurface({ dealId }: { dealId: string }) {
  const [decisionRecorded, setDecisionRecorded] = useState(false);
  useEffect(() => { setDecisionRecorded(new URLSearchParams(window.location.search).get("state") === "recorded" || window.localStorage.getItem(`analysis-decision-recorded:${dealId}`) === "true"); }, [dealId]);
  const [running, setRunning] = useState(false);
  const [validated, setValidated] = useState(false);
  const [cashCorrected, setCashCorrected] = useState(false);
  const currentCash = cashCorrected ? "4.7" : "6.2";
  const difference = cashCorrected ? "0.0" : "1.5";
  const runValidation = () => { if (!decisionRecorded || running) return; setRunning(true); window.setTimeout(() => { setRunning(false); setValidated(true); setCashCorrected(true); }, 450); };
  const groups = [
    ["Recalculation required", "critical", "Valuation-workbook cash bridge and equity value output.", "2", validated ? "Completed" : "Pending"],
    ["Regeneration required", "warning", "Analysis-workbook Reader Copy and CIM value statement.", "2", validated ? "Rev 0.4 generated" : "Blocked"],
    ["Re-review required", "warning", "Native/Reader parity, QC Finding, and Professional Usability.", "3", "Banker re-review required"],
    ["External circulation blocked", "critical", "Any authorization for Rev 0.3 does not carry forward to Rev 0.4.", "1", "Not authorized"],
    ["Checked and unaffected", "success", "Buyer, NDA, Data-Room Access, and process objects that do not depend on this Cash basis.", "11", "State preserved"],
  ] as const;
  return <div className="dc-analysis-page" data-od-id="analysis-screen">
    <PageHeader eyebrow="ANL-014 v3 · deterministic validation" title="Analysis" description="Separate AI Proposals, Banker Decisions, and repeatable calculations while showing actual inputs, rules, differences, and downstream Impact." actions={validated ? <a className="dc-button" href={`${dealBase(dealId)}/review-readiness/package-readiness`}>Inspect package readiness</a> : <button type="button" data-od-id="run-deterministic-validation" onClick={runValidation} disabled={!decisionRecorded || running}>{running ? "Recalculating…" : "Run deterministic validation"}</button>} />
    {!decisionRecorded ? <section className="dc-analysis-blocker" data-od-id="analysis-material-blocker"><div><span className="dc-eyebrow">Waiting for user</span><h2>A material Human Decision has not been recorded</h2><p>Forecast reconciliation and affected Deliverables are blocked. Buyer research and other work that does not depend on this Claim can continue.</p></div><a className="dc-button" href={`${dealBase(dealId)}/evidence-decisions/control-review`}>Open Evidence &amp; Decisions</a></section> : null}
    <section className="dc-analysis-workbench" data-od-id="deterministic-validation-workbench"><div className="dc-analysis-section-head"><div><span className="dc-eyebrow">VAL-009 · EV-to-equity tie-out</span><h2>Deterministic validation result</h2></div><StatusBadge tone={running ? "info" : validated ? "success" : "critical"}>{running ? "Recalculating" : validated ? "Mechanical Validity passed" : "Mechanical Validity failed"}</StatusBadge></div><div className="dc-analysis-grid"><div><h3>Inputs and control records</h3><dl><div><dt>Controlled EBITDA</dt><dd>$17.8m <small>{decisionRecorded ? "DEC-014" : "Decision required"}</small></dd></div><div><dt>AI extraction v1 · Cash</dt><dd className="dc-struck">$6.2m <small>Historical Proposal · Not overwritten</small></dd></div><div><dt>Current Cash basis</dt><dd className="dc-analysis-number">${currentCash}m <small>{cashCorrected ? "Correction v2 · DEC-014" : "Uncorrected"}</small></dd></div><div><dt>Rule set</dt><dd className="dc-mono">EV-EQ-TIE-004 v2 <small>Exact unit, period, and sign rules</small></dd></div></dl></div><div><h3>Result</h3><div className={`dc-analysis-result ${validated ? "is-passed" : "is-failed"}`}><span className="dc-eyebrow">Current difference</span><strong>${difference}m</strong><p>{validated ? "Deterministic validation closed the difference caused by the Cash extraction. This result does not establish Professional Usability." : "The Cash extraction does not match the Native Locator, so validation remains open. It can be rerun after the material Decision."}</p></div><p className="dc-analysis-footnote">Mechanical validity is necessary but does not establish Professional Usability.</p></div></div><div className="dc-job-strip" data-od-id="analysis-job-strip"><span className="dc-mono">JOB-0098</span><strong>{running ? "running" : validated ? "completed" : decisionRecorded ? "ready to run" : "waiting-for-user"}</strong><span>{running ? "Recalculating the cash bridge, units, tie-out, and dependency Impact." : validated ? "Extraction, unit normalization, tie-out, and dependency checks are recorded." : "Accepted extraction and unit-normalization progress remains unchanged."}</span><span className="dc-mono">{running ? "Progress · deterministic steps 2 / 4" : `Last heartbeat · ${validated ? "15:16:22" : "15:04:09"}`}</span></div><p className="dc-inline-notice" role="status" aria-live="polite">{running ? "Deterministic engine is evaluating pinned inputs; no authoritative Fact or Decision is created." : validated ? "Validation receipt VAL-009 recorded. Downstream Impact remains independently reviewable." : "Formula/cache presence alone cannot satisfy Calculation Integrity."}</p></section>
    <section className="dc-analysis-impact" data-od-id="impact-assessment"><div className="dc-analysis-section-head"><div><span className="dc-eyebrow">IA-014 · task-oriented impact</span><h2>Downstream Impact of Cash $6.2m → $4.7m</h2></div><span className="dc-mono">3 direct dependencies · 8 affected objects · 11 checked and unaffected (all synthetic demo data)</span></div><div className="dc-impact-groups">{groups.map(([label, tone, detail, count, status]) => <article key={label} data-impact-group={label}><span className="impact-count dc-mono">{count}</span><div><strong>{label}</strong><p>{detail}</p></div><StatusBadge tone={label === "Checked and unaffected" ? "neutral" : tone as Tone}>{status}</StatusBadge></article>)}</div><div className="dc-page-actions"><a className="dc-button dc-button-secondary" data-od-id="open-analysis-object" href={`${dealBase(dealId)}/analysis/analyses/anl-014`}>Open Analysis object</a><a className="dc-button" data-od-id="open-impact-object" href={`${dealBase(dealId)}/review-readiness/impact-assessments/ia-014`}>Inspect full Impact <span aria-hidden="true">→</span></a></div></section>
  </div>;
}

